let recorder=null,recordStream=null,recordChunks=[],recordTimeout=null,voiceMode=false,voiceRole=null,voiceProcessing=false,currentAudio=null,speechController=null;
function stopVoice(){voiceMode=false;speechController?.abort();if(recorder?.state==='recording')recorder.stop();recordStream?.getTracks().forEach(t=>t.stop());if(currentAudio){currentAudio.pause();URL.revokeObjectURL(currentAudio.src);currentAudio=null}if('speechSynthesis'in window)window.speechSynthesis.cancel()}
function renderVoiceSettings(){screen.innerHTML=`<section class="view">${title('语音小客厅','A VOICE TO KEEP YOU COMPANY')}<div class="notice">语音聊天会把录音发送到你配置的 API 转成文字，再生成回复。服务商需支持语音接口与跨域请求。</div><form id="voiceForm"><label>录音转文字模型<input name="stt" value="${escapeHtml(voiceSettings.stt)}" placeholder="服务商的 transcription 模型名称"></label><label>文字转语音模型 · 可选<input name="tts" value="${escapeHtml(voiceSettings.tts)}" placeholder="服务商的 speech 模型名称"></label><label>声音名称<input name="voice" value="${escapeHtml(voiceSettings.voice)}" placeholder="服务商支持的 voice 名称"></label><label class="check"><input name="autoPlay" type="checkbox" ${voiceSettings.autoPlay?'checked':''}>文字聊天回复后自动播放语音</label><button class="primary full">保存语音设置</button></form><p class="api-note">使用当前 API 地址和 Key，分别调用 /audio/transcriptions 与 /audio/speech。未填写语音合成模型时，尝试浏览器朗读；这不是实时全双工通话。聊天右上角「⋯」可进入轮流说话的语音聊天。</p><button class="secondary full" id="testVoice">试听一句问候</button></section>`;$('#voiceForm').onsubmit=e=>{e.preventDefault();const f=e.target;voiceSettings={stt:f.stt.value.trim(),tts:f.tts.value.trim(),voice:f.voice.value.trim()||'alloy',autoPlay:f.autoPlay.checked};localSave('voiceSettings',voiceSettings);toast('语音设置已保存')};$('#testVoice').onclick=()=>playSpeech('你好，欢迎回到你的玫瑰小宫殿。').catch(e=>toast(friendly(e)))}
async function playSpeech(text){if(phoneLocked)return;speechController?.abort();speechController=new AbortController();const speechSignal=AbortSignal.any([speechController.signal,AbortSignal.timeout(60000)]);if(currentAudio){currentAudio.pause();URL.revokeObjectURL(currentAudio.src);currentAudio=null}if('speechSynthesis'in window)speechSynthesis.cancel();
  if(!voiceSettings.tts){if(!('speechSynthesis'in window))throw Error('此浏览器不支持朗读，请配置语音合成模型');const utterance=new SpeechSynthesisUtterance(text);utterance.lang='zh-CN';utterance.rate=.95;speechSynthesis.speak(utterance);return}
  if(!apiReady())throw Error('请先连接 API');const res=await fetch(PalaisCore.apiURL(config.base,'audio/speech'),{method:'POST',headers:{Authorization:'Bearer '+key,'Content-Type':'application/json'},body:JSON.stringify({model:voiceSettings.tts,input:text.slice(0,4000),voice:voiceSettings.voice,response_format:'mp3'}),signal:speechSignal});if(!res.ok){let data;try{data=await res.json()}catch{}throw Error('语音合成失败（HTTP '+res.status+'）'+(data?.error?.message?'：'+data.error.message:''))}const blob=await res.blob();if(!blob.type.startsWith('audio/')&&blob.type!=='application/octet-stream')throw Error('接口没有返回音频');if(phoneLocked)return;const url=URL.createObjectURL(blob),audio=new Audio(url);currentAudio=audio;audio.onended=()=>{URL.revokeObjectURL(url);if(currentAudio===audio)currentAudio=null};try{await audio.play()}catch{URL.revokeObjectURL(url);throw Error('自动播放被浏览器阻止，请点回复旁的朗读按钮')}
}
function openVoiceChat(r){if(busy){toast('等本轮聊天结束后再开始语音');return}if(!apiReady()){requireAPI();return}if(!voiceSettings.stt){toast('请先填写录音转文字模型');go('voice');return}voiceMode=true;voiceRole=r;const d=panel(`<div class="eyebrow">LET YOUR VOICE REACH ME</div><h2>与${escapeHtml(r.name)}语音聊天</h2><div class="voice-orb">♫</div><p class="voice-status" id="voiceStatus">点开始说话，单次最多 60 秒。</p><div class="actions"><button class="primary" id="startCallRecording">开始说话</button><button class="secondary" id="stopCallRecording" disabled>说完并发送</button></div><p class="api-note">录音会发送至你的 API。转写内容会保存到聊天记录；回复会尝试播放语音。</p><button class="secondary full" id="closeVoiceChat">结束语音聊天</button>`);$('#startCallRecording').onclick=()=>startRecording(r,true);$('#stopCallRecording').onclick=()=>finishRecording();$('#closeVoiceChat').onclick=()=>{stopVoice();d.close()};d.addEventListener('close',stopVoice,{once:true})}
async function startRecording(r,inCall=false){if(phoneLocked||busy||voiceProcessing){toast('请等本轮回复结束');return}if(recorder?.state==='recording'){finishRecording();return}if(!apiReady()){requireAPI();return}if(!voiceSettings.stt){toast('先在语音设置中填写录音转文字模型');go('voice');return}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('此浏览器不支持录音，请使用支持录音的浏览器');return}
  try{recordStream=await navigator.mediaDevices.getUserMedia({audio:true});if(phoneLocked){recordStream.getTracks().forEach(t=>t.stop());return}const mime=['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(m=>MediaRecorder.isTypeSupported(m));recorder=new MediaRecorder(recordStream,mime?{mimeType:mime}:{});recordChunks=[];const started=Date.now();recorder.ondataavailable=e=>{if(e.data.size)recordChunks.push(e.data)};
    recorder.onstop=async()=>{clearTimeout(recordTimeout);recordStream?.getTracks().forEach(t=>t.stop());const blob=new Blob(recordChunks,{type:recorder.mimeType||'audio/webm'});recorder=null;if(phoneLocked||inCall&&!voiceMode)return;voiceProcessing=true;voiceStatus('正在把录音转成文字…');setCallButtons(true);const mic=$('#recordMessage');if(mic)mic.textContent='…';try{if(Date.now()-started<500||!blob.size)throw Error('录音太短，请再说一次');const form=new FormData();form.append('file',blob,blob.type.includes('mp4')?'recording.m4a':'recording.webm');form.append('model',voiceSettings.stt);const res=await fetch(PalaisCore.apiURL(config.base,'audio/transcriptions'),{method:'POST',headers:{Authorization:'Bearer '+key},body:form,signal:AbortSignal.timeout(60000)});let data;try{data=await res.json()}catch{throw Error('语音转写接口未返回有效 JSON')}if(!res.ok)throw Error('语音转写失败（HTTP '+res.status+'）'+(data.error?.message?'：'+data.error.message:''));if(typeof data.text!=='string'||!data.text.trim())throw Error('没有识别到文字，请再说一次');if(phoneLocked||inCall&&!voiceMode)return;
      if(inCall){voiceStatus('你说：'+data.text+'\n正在等待回复…');await sendMessage(r,data.text.trim());voiceStatus('这一轮结束了，可以继续说话。')}else{if(tab==='chat'&&current===r.id&&$('#composer textarea')){$('#composer textarea').value=data.text.trim();toast('录音已转为文字，确认后发送')}else toast('已离开原聊天，请回到对话后重新录音')}
    }catch(err){toast(friendly(err));voiceStatus(friendly(err))}finally{voiceProcessing=false;setCallButtons(false);if($('#recordMessage'))$('#recordMessage').textContent='♫'}};
    recorder.start();recordTimeout=setTimeout(finishRecording,60000);voiceStatus('正在听你说话…');if(inCall){$('#startCallRecording').disabled=true;$('#stopCallRecording').disabled=false}else if($('#recordMessage'))$('#recordMessage').textContent='■';
  }catch(err){toast(err.name==='NotAllowedError'?'麦克风权限未开启，请在浏览器中允许录音':friendly(err));recordStream?.getTracks().forEach(t=>t.stop())}
}
function voiceStatus(text){if($('#voiceStatus'))$('#voiceStatus').textContent=text}
function setCallButtons(processing){if($('#startCallRecording'))$('#startCallRecording').disabled=processing;if($('#stopCallRecording'))$('#stopCallRecording').disabled=true}
function finishRecording(){if(recorder?.state==='recording')recorder.stop()}
